impl Solution{pub fn decode_string(s:String)->String{let mut nums=vec![];let mut prev=vec![];let mut cur=String::new();let mut n=0usize;for c in s.chars(){if c.is_ascii_digit(){n=n*10+c.to_digit(10).unwrap()as usize}else if c=='['{nums.push(n);prev.push(cur);cur=String::new();n=0}else if c==']'{let x=cur;cur=prev.pop().unwrap();let k=nums.pop().unwrap();for _ in 0..k{cur.push_str(&x)}}else{cur.push(c)}}cur}}
